/**
 * Test Suite for #{#upr2a} - Batch upload isolates per-file failures
 *
 * Specification: specs/specifications/upload-pipeline-resilience.md
 * Authority: developer
 *
 * Code already implements this in src/routes/receipts/+page.svelte (onFilesChanged).
 * These tests guard against regression. Two layers:
 *  (a) source-introspection — the .svelte file contains the right structural pattern
 *  (b) logic-level — a small helper mirrors the loop semantics and is unit-tested
 */
describe('#{#upr2a} Batch upload per-file isolation', () => {
	const pagePath = join(process.cwd(), 'src/routes/receipts/+page.svelte');
	const pageContent = readFileSync(pagePath, 'utf-8');

	describe('source-introspection — onFilesChanged structure', () => {
		it('iterates files with a for-loop inside the handler', () => {
			expect(pageContent).toMatch(/function onFilesChanged[\s\S]*?for\s*\([^)]*of\s+files\s*\)/);
		});

		it('wraps each uploadAndCreate call in its own try/catch', () => {
			expect(pageContent).toMatch(
				/for\s*\([^)]*of\s+files\s*\)\s*\{[\s\S]*?try\s*\{[\s\S]*?uploadAndCreate[\s\S]*?\}\s*catch/
			);
		});

		it('accumulates per-file failures into a list', () => {
			expect(pageContent).toMatch(/failures\s*:\s*string\[\]\s*=\s*\[\]/);
			expect(pageContent).toMatch(/failures\.push/);
		});

		it('prepends each successful receipt to allReceipts as it completes', () => {
			// The success branch sets allReceipts = [receipt, ...allReceipts]
			expect(pageContent).toMatch(/allReceipts\s*=\s*\[\s*receipt\s*,\s*\.\.\.allReceipts\s*\]/);
		});

		it('builds a "Failed N of M" summary error when at least one upload failed', () => {
			expect(pageContent).toMatch(/Failed \$\{failures\.length\} of \$\{files\.length\} receipt/);
		});

		it('resets the file input value at the end so the same file can be re-uploaded', () => {
			expect(pageContent).toMatch(/input\.value\s*=\s*['"][^'"]*['"]/);
		});

		it('sets uploading=true before the loop and uploading=false after', () => {
			// Both assignments live in onFilesChanged; failure here means the
			// flag toggling has been removed/renamed.
			expect(pageContent).toMatch(/uploading\s*=\s*true/);
			expect(pageContent).toMatch(/uploading\s*=\s*false/);
		});
	});

